cat > "$TEMP/pvfx_patch.js" <<'EOF'
const fs=require('fs');
const dir='C:/GameJam/Glyphbound/Plugins/GBPixelVfx/Bake/Jobs/';
for(const f of fs.readdirSync(dir)){
  const j=JSON.parse(fs.readFileSync(dir+f,'utf8'));
  const c=j.Capture; const nc={};
  for(const k of Object.keys(c)){ if(k==='DistanceCm'){ nc.Projection='Perspective'; nc.FovDeg=10; } else nc[k]=c[k]; }
  j.Capture=nc;
  j.Pixel.MinIslandPixels=2; j.Pixel.FillHoles=false;
  j.Light.TrackMode='Baked';
  j.World.Lit = (j.Id==='FluidSmoke');
  fs.writeFileSync(dir+f, JSON.stringify(j,null,2)+'\n');
}
// script: fixed step for bakes, RT override per Astra
const sp='C:/GameJam/Tools/Jam/PixelVfx-Jam.ps1';
let s=fs.readFileSync(sp,'utf8');
const a="$argList += '-ini:Engine:[/Script/Engine.RendererSettings]:r.RayTracing=True,[/Script/Engine.RendererSettings]:r.Lumen.HardwareRayTracing=True'";
const b="$argList += @('-dx12', '-ini:Engine:[/Script/Engine.RendererSettings]:r.RayTracing=1,r.Lumen.HardwareRayTracing=1')";
if(!s.includes(a)) throw new Error('rt line not found');
s=s.split(a).join(b);
const c1="    if (-not $Window) { $argList += '-RenderOffscreen' }";
const c2="    if (-not $Window) { $argList += '-RenderOffscreen' }\r\n    # Bakes count simulation frames: the fixed step must be in place before the first frame (BeginPlay is too late for it).\r\n    if ($Action -eq 'Bake') { $argList += @('-UseFixedTimeStep', '-FPS=60') }";
const c1n=c1; 
if(!s.includes(c1)) throw new Error('offscreen line not found');
s=s.split(c1).join(c2.split('\r\n').join(s.includes('\r\n')?'\r\n':'\n'));
fs.writeFileSync(sp,s);
// brief: camera line
const bp='C:/GameJam/Prompts/pixelvfx_implement.md';
let t=fs.readFileSync(bp,'utf8');
const o1="4. A `USceneCaptureComponent2D`: orthographic (unless the notes say perspective), `OrthoWidth = WidthCm`, placed `DistanceCm` away from `CenterCm` along the view direction";
const o2="4. A `USceneCaptureComponent2D`: **long-lens perspective** (`Capture.FovDeg`, default 10; see the notes, item 1; \"Ortho\" stays as an option with `OrthoWidth = WidthCm`), placed at `(WidthCm / 2) / tan(FovDeg / 2)` from `CenterCm` along the view direction";
if(!t.includes(o1)) throw new Error('brief line not found');
t=t.split(o1).join(o2);
fs.writeFileSync(bp,t);
console.log('ok');
EOF
