cat > "$TEMP/pvfx_tune2.js" <<'EOF'
const fs=require('fs');
const dir='C:/GameJam/Glyphbound/Plugins/GBPixelVfx/Bake/Jobs/';
const rd=f=>JSON.parse(fs.readFileSync(dir+f,'utf8'));
const wr=(f,j)=>fs.writeFileSync(dir+f,JSON.stringify(j,null,2)+'\n');
const FIRE=["#4B0F0F","#BC2A12","#F03416","#F3610B","#E2DE9C","#F5F3CF"];
const SMOKE=["#262827","#373837","#434848","#555957"];
let fire=rd('FluidFire.json');
Object.assign(fire.Pixel,{Gamma:0.7,LevelsPercentile:0.95});
wr('FluidFire.json',fire);
let arc=rd('FluidArcaneFire.json');
Object.assign(arc.Pixel,{Gamma:0.7,LevelsPercentile:0.95});
wr('FluidArcaneFire.json',arc);
let smoke=rd('FluidSmoke.json');
smoke.Comment='Niagara Fluids 3D gas smoke (engine template): a column of dark smoke over a fire at its base. Loop. Split mapping: the fire on the fire ramp, the smoke on dark iron; the fire drives the light.';
Object.assign(smoke.Pixel,{ColorMode:'Split',AlphaMode:'Max',HotLuminance:0.5,HotSaturation:0.6,Ramps:[FIRE,SMOKE],Gamma:0.7,LevelsPercentile:0.95});
Object.assign(smoke.Light,{Enabled:true,Intensity:10.0,RadiusCm:800});
smoke.World.Lit=false; smoke.World.Glow=1.0;
wr('FluidSmoke.json',smoke);
let ex=rd('FluidExplosion.json');
Object.assign(ex.Pixel,{HotLuminance:0.45,HotSaturation:0.75});
wr('FluidExplosion.json',ex);
EOF
node "$TEMP/pvfx_tune2.js" && echo tuned

