1	// UGBPixelVfxComponent: quad + baked light track playback.
2	#include "GBPixelVfxComponent.h"
3	
4	#include "Camera/PlayerCameraManager.h"
5	#include "Components/PointLightComponent.h"
6	#include "Components/StaticMeshComponent.h"
7	#include "Components/PointLightComponent.h"
8	#include "Components/StaticMeshComponent.h"
9	#include "Engine/StaticMesh.h"
10	#include "Engine/Texture2D.h"
11	#include "GBPixelVfxSubsystem.h"
12	#include "Kismet/GameplayStatics.h"
13	#include "Materials/MaterialInstanceDynamic.h"
14	
15	namespace GBPixelVfxComponentLocal
16	{
17		// Quad mesh: /Engine/BasicShapes/Cube, scaled flat (see EnsureBuilt). The brief
18		// names /Engine/BasicShapes/Plane, but the Plane does not rasterize in -game here:
19		// a Plane with the default material, facing the camera, registered and visible,
20		// never appears (both facings tested), while a Cube with the identical setup
21		// renders correctly. The Plane asset itself is healthy (4 verts, 2 tris, XY plane).
22		// The box's front face carries the sprite; side faces sample transparent atlas
23		// edge texels and are discarded by the opacity mask.
24		const TCHAR* MeshPath = TEXT("/Engine/BasicShapes/Cube.Cube");
25		const TCHAR* SpriteMaterialPath = TEXT("/Game/Glyphbound/Materials/M_PixelVfxSprite.M_PixelVfxSprite");
26		const TCHAR* LitMaterialPath = TEXT("/Game/Glyphbound/Materials/M_PixelVfxSpriteLit.M_PixelVfxSpriteLit");
27		const TCHAR* FallbackMaterialPath = TEXT("/Engine/BasicShapes/BasicShapeMaterial.BasicShapeMaterial");
28	}
29	
30	UGBPixelVfxComponent::UGBPixelVfxComponent()
31	{
32		PrimaryComponentTick.bCanEverTick = true;
33		PrimaryComponentTick.bStartWithTickEnabled = true;
34	}
35	
36	bool UGBPixelVfxComponent::Play(FName ClipId, bool bRestart)
37	{
38		if (!bRestart && bPlaying && CurrentClipId == ClipId && CurrentClip.IsValid())
39		{
40			return true;
41		}
42		UGameInstance* GameInstance = nullptr;
43		if (UWorld* World = GetWorld())
44		{
45			GameInstance = World->GetGameInstance();
46		}
47		UGBPixelVfxSubsystem* Subsystem = GameInstance ? GameInstance->GetSubsystem<UGBPixelVfxSubsystem>() : nullptr;
48		if (!Subsystem)
49		{
50			UE_LOG(LogGBPixelVfx, Warning, TEXT("PixelVfx Play '%s': no subsystem."), *ClipId.ToString());
51			return false;
52		}
53		const FGBPixelVfxClip* Found = Subsystem->FindClip(ClipId);
54		if (!Found)
55		{
56			return false;
57		}
58		UTexture2D* Atlas = Subsystem->GetAtlas(ClipId);
59		if (!Atlas)
60		{
61			return false;
62		}
63		CurrentClip = MakeShared<FGBPixelVfxClip>(*Found);
64		CurrentClipId = ClipId;
65		if (!bLightCastsShadowsSet)
66		{
67			bLightCastsShadows = CurrentClip->Light.bCastShadows;
68		}
69		PlayTime = StartTimeOffset;
70		CurrentFrame = -1;
71		bPlaying = true;
72		EnsureBuilt();
73		UpdateFrame(true);
74		return true;
75	}
76	
77	void UGBPixelVfxComponent::Stop()
78	{
79		bPlaying = false;
80		if (ClipLight)
81		{
82			ClipLight->DestroyComponent();
83			ClipLight = nullptr;
84		}
85		if (Quad)
86		{
87			Quad->DestroyComponent();
88			Quad = nullptr;
89		}
90		QuadMaterial = nullptr;
91	}
92	
93	void UGBPixelVfxComponent::EnsureBuilt()
94	{
95		if (!CurrentClip.IsValid())
96		{
97			return;
98		}
99		if (!Quad)
100		{
101			UStaticMesh* PlaneMesh = Cast<UStaticMesh>(StaticLoadObject(UStaticMesh::StaticClass(), nullptr,
102				GBPixelVfxComponentLocal::MeshPath));
103			if (!PlaneMesh)
104			{
105				UE_LOG(LogGBPixelVfx, Warning, TEXT("PixelVfx: cannot load the quad mesh %s."),
106					GBPixelVfxComponentLocal::MeshPath);
107				return;
108			}
109			Quad = NewObject<UStaticMeshComponent>(GetOwner() ? static_cast<UObject*>(GetOwner()) : static_cast<UObject*>(this), NAME_None, RF_Transient);
110			Quad->SetMobility(EComponentMobility::Movable);
111			Quad->AttachToComponent(this, FAttachmentTransformRules::KeepRelativeTransform);
112			Quad->SetStaticMesh(PlaneMesh);
113			Quad->SetCollisionEnabled(ECollisionEnabled::NoCollision);
114			Quad->SetCastShadow(false);
115			Quad->SetVisibleInRayTracing(true);
116			Quad->SetAffectDynamicIndirectLighting(true);
117			Quad->bVisibleInReflectionCaptures = true;
118			// Final size is known now (clip + SizeScale): set it before registering so the
119			// initial render bounds are correct.
120			Quad->SetRelativeScale3D(FVector(
121				FMath::Max(0.01f, CurrentClip->WorldWidthCm * SizeScale / 100.f),
122				FMath::Max(0.01f, CurrentClip->WorldHeightCm * SizeScale / 100.f), 1.f));
123			Quad->RegisterComponent();
124			Quad->MarkRenderStateDirty();
125		}
126		RefreshClipMaterial();
127		RebuildLight();
128	}
129	
130	void UGBPixelVfxComponent::RefreshClipMaterial()
131	{
132		// Clip-dependent material state is refreshed on every successful Play so that
133		// switching clips without Stop() picks up the new atlas, variant and glow.
134		if (!Quad || !CurrentClip.IsValid())
135		{
136			return;
137		}
138		const TCHAR* MaterialPath = CurrentClip->bLit
139			? GBPixelVfxComponentLocal::LitMaterialPath
140			: GBPixelVfxComponentLocal::SpriteMaterialPath;
141		UMaterialInterface* Base = Cast<UMaterialInterface>(StaticLoadObject(UMaterialInterface::StaticClass(),
142			nullptr, MaterialPath));
143		if (!Base && !bQuadMissingMaterialWarned)
144		{
145			bQuadMissingMaterialWarned = true;
146			UE_LOG(LogGBPixelVfx, Warning, TEXT("PixelVfx: material %s is missing, falling back to %s."),
147				MaterialPath, GBPixelVfxComponentLocal::FallbackMaterialPath);
148			Base = Cast<UMaterialInterface>(StaticLoadObject(UMaterialInterface::StaticClass(),
149				nullptr, GBPixelVfxComponentLocal::FallbackMaterialPath));
150		}
151		if (!Base)
152		{
153			return;
154		}
155		QuadMaterial = UMaterialInstanceDynamic::Create(Base, this);
156		UGBPixelVfxSubsystem* Subsystem = nullptr;
157		if (UWorld* World = GetWorld())
158		{
159			if (UGameInstance* GameInstance = World->GetGameInstance())
160			{
161				Subsystem = GameInstance->GetSubsystem<UGBPixelVfxSubsystem>();
162			}
163		}
164		UTexture2D* Atlas = Subsystem ? Subsystem->GetAtlas(CurrentClipId) : nullptr;
165		if (Atlas)
166		{
167			QuadMaterial->SetTextureParameterValue(TEXT("Atlas"), Atlas);
168		}
169		QuadMaterial->SetVectorParameterValue(TEXT("Tint"), FLinearColor::White);
170		QuadMaterial->SetScalarParameterValue(TEXT("Glow"), CurrentClip->Glow);
171		if (Quad)
172		{
173			Quad->SetMaterial(0, QuadMaterial);
174		}
175	}
176	
177	void UGBPixelVfxComponent::RebuildLight()
178	{
179		const bool bWantsLight = CurrentClip.IsValid() && CurrentClip->Light.bEnabled && bEnableLight;
180		if (!bWantsLight)
181		{
182			if (ClipLight)
183			{
184				ClipLight->DestroyComponent();
185				ClipLight = nullptr;
186			}
187			return;
188		}
189		if (!ClipLight)
190		{
191			ClipLight = NewObject<UPointLightComponent>(GetOwner() ? static_cast<UObject*>(GetOwner()) : static_cast<UObject*>(this), NAME_None, RF_Transient);
192			ClipLight->SetMobility(EComponentMobility::Movable);
193			ClipLight->SetIntensityUnits(ELightUnits::Candelas);
194			ClipLight->AttachToComponent(this, FAttachmentTransformRules::KeepRelativeTransform);
195			ClipLight->RegisterComponent();
196		}
197		ClipLight->SetLightColor(CurrentClip->Light.Color);
198		ClipLight->SetAttenuationRadius(CurrentClip->Light.RadiusCm * FMath::Max(0.01f, SizeScale));
199		ClipLight->SetCastShadows(bLightCastsShadows);
200	}
201	
202	void UGBPixelVfxComponent::UpdateFrame(bool bForce)
203	{
204		if (!bPlaying || !CurrentClip.IsValid())
205		{
206			return;
207		}
208		bool bOutFinished = false;
209		const int32 Frame = FGBPixelVfxClip::FrameAtTime(*CurrentClip, PlayTime, bOutFinished);
210		if (bOutFinished)
211		{
212			Stop();
213			if (bAutoDestroyOwnerWhenFinished && GetOwner())
214			{
215				GetOwner()->Destroy();
216			}
217			return;
218		}
219		if (Frame == CurrentFrame && !bForce)
220		{
221			return;
222		}
223		CurrentFrame = Frame;
224		const FVector4f Rect = FGBPixelVfxClip::FrameRect(*CurrentClip, Frame);
225		if (QuadMaterial)
226		{
227			// The frame rect rides as four scalars (see make_pixelvfx_material.py): masks on a
228			// uniform that feeds the texture UVs fail to compile, so there is no vector swizzle.
229			// The Plane mesh is assumed to run U along +X and V along +Y with V = 0 at the bottom;
230			// UE samples (0, 0) at the image top-left, so V is flipped here.
231			QuadMaterial->SetScalarParameterValue(TEXT("FrameU"), Rect.X);
232			QuadMaterial->SetScalarParameterValue(TEXT("FrameV"), Rect.Y + Rect.W);
233			QuadMaterial->SetScalarParameterValue(TEXT("FrameW"), Rect.Z);
234			QuadMaterial->SetScalarParameterValue(TEXT("FrameH"), -Rect.W);
235		}
236		if (ClipLight && CurrentClip->Light.bEnabled)
237		{
238			float TrackValue = 1.f;
239			if (CurrentClip->Light.TrackMode.Equals(TEXT("Constant"), ESearchCase::IgnoreCase)
240				|| CurrentClip->Light.Track.Num() != CurrentClip->FrameCount)
241			{
242				TrackValue = 1.f;
243			}
244			else if (CurrentClip->Light.Track.IsValidIndex(Frame))
245			{
246				TrackValue = CurrentClip->Light.Track[Frame];
247			}
248			ClipLight->SetIntensity(CurrentClip->Light.Intensity * TrackValue * LightIntensityScale);
249		}
250	}
251	
252	FVector UGBPixelVfxComponent::PivotWorldOffset() const
253	{
254		// Quad-local position of the pivot point; the quad is shifted so it lands on the component.
255		if (!CurrentClip.IsValid())
256		{
257			return FVector::ZeroVector;
258		}
259		const float W = CurrentClip->WorldWidthCm * SizeScale;
260		const float H = CurrentClip->WorldHeightCm * SizeScale;
261		return FVector((CurrentClip->PivotU - 0.5f) * W, (0.5f - CurrentClip->PivotV) * H, 0.f);
262	}
263	
264	void UGBPixelVfxComponent::UpdateQuadTransform()
265	{
266		if (!Quad || !CurrentClip.IsValid())
267		{
268			return;
269		}
270		// Quad size follows the clip and SizeScale (set before RegisterComponent too).
271		const float W = CurrentClip->WorldWidthCm * SizeScale;
272		const float H = CurrentClip->WorldHeightCm * SizeScale;
273		Quad->SetRelativeScale3D(FVector(FMath::Max(0.01f, W / 100.f), FMath::Max(0.01f, H / 100.f), 1.f));
274	
275		EGBPixelVfxFacing Facing = CurrentClip->Facing;
276		if (!FacingOverride.IsNone())
277		{
278			const FString Text = FacingOverride.ToString();
279			if (Text.Equals(TEXT("Billboard"), ESearchCase::IgnoreCase)) Facing = EGBPixelVfxFacing::Billboard;
280			else if (Text.Equals(TEXT("Upright"), ESearchCase::IgnoreCase)) Facing = EGBPixelVfxFacing::Upright;
281			else if (Text.Equals(TEXT("Ground"), ESearchCase::IgnoreCase)) Facing = EGBPixelVfxFacing::Ground;
282			else if (Text.Equals(TEXT("Fixed"), ESearchCase::IgnoreCase)) Facing = EGBPixelVfxFacing::Fixed;
283		}
284	
285		const FVector CompLoc = GetComponentLocation();
286		FQuat R = GetComponentQuat();
287		if (Facing == EGBPixelVfxFacing::Fixed)
288		{
289			R = GetComponentQuat();
290		}
291		else if (Facing == EGBPixelVfxFacing::Ground)
292		{
293			// The quad stays flat (normal = world +Z) while following the component's yaw.
294			const FRotator CompRot = GetComponentQuat().Rotator();
295			R = FRotator(0.f, CompRot.Yaw, 0.f).Quaternion();
296		}
297		else
298		{
299			FVector CamPos = FVector::ZeroVector;
300			FVector CamUp = FVector::UpVector;
301			bool bHasCamera = false;
302			if (UWorld* World = GetWorld())
303			{
304				if (APlayerCameraManager* Manager = UGameplayStatics::GetPlayerCameraManager(World, 0))
305				{
306					CamPos = Manager->GetCameraLocation();
307					CamUp = Manager->GetCameraRotation().RotateVector(FVector::UpVector);
308					bHasCamera = true;
309				}
310			}
311			if (bHasCamera)
312			{
313				// The direction uses the COMPONENT location (not the quad's): the pivot
314				// must land on the component for every facing mode.
315				FVector ToCam = CamPos - CompLoc;
316				if (Facing == EGBPixelVfxFacing::Upright)
317				{
318					ToCam.Z = 0.f;
319					CamUp = FVector::UpVector;
320				}
321				if (ToCam.SizeSquared() > 1.f)
322				{
323					const FVector ZAxis = ToCam.GetSafeNormal();
324					FVector XAxis = FVector::CrossProduct(CamUp, ZAxis);
325					if (XAxis.SizeSquared() < 1.e-6f)
326					{
327						XAxis = FVector(1.f, 0.f, 0.f);
328					}
329					else
330					{
331						XAxis.Normalize();
332					}
333					const FVector YAxis = FVector::CrossProduct(ZAxis, XAxis);
334					R = FMatrix(XAxis, YAxis, ZAxis, FVector::ZeroVector).Rotator().Quaternion();
335				}
336				else
337				{
338					R = Quad->GetComponentQuat();
339				}
340			}
341			else
342			{
343				// No player camera: keep the last rotation.
344				R = Quad->GetComponentQuat();
345			}
346		}
347	
348		FVector QuadLoc = CompLoc;
349		FVector LightLoc = CompLoc;
350		FGBPixelVfxClip::ComputeQuadAndLightPlacement(*CurrentClip, SizeScale, CompLoc, R, QuadLoc, LightLoc);
351		Quad->SetWorldLocationAndRotation(QuadLoc, R);
352	
353		if (ClipLight)
354		{
355			ClipLight->SetWorldLocation(LightLoc);
356		}
357	}
358	
359	void UGBPixelVfxComponent::TickComponent(float DeltaTime, ELevelTick TickType,
360		FActorComponentTickFunction* ThisTickFunction)
361	{
362		Super::TickComponent(DeltaTime, TickType, ThisTickFunction);
363		if (!bPlaying || !CurrentClip.IsValid())
364		{
365			return;
366		}
367		PlayTime += DeltaTime * PlayRate;
368		UpdateFrame(false);
369		UpdateQuadTransform();
370	}
371	
372	void UGBPixelVfxComponent::GetQuadWorldBounds(FVector& OutOrigin, FVector& OutExtent) const
373	{
374		OutOrigin = FVector::ZeroVector;
375		OutExtent = FVector::ZeroVector;
376		if (Quad && Quad->GetStaticMesh())
377		{
378			const FBoxSphereBounds MeshBounds = Quad->GetStaticMesh()->GetBounds();
379			OutOrigin = Quad->GetComponentTransform().TransformPosition(MeshBounds.Origin);
380			OutExtent = Quad->GetComponentTransform().TransformVector(MeshBounds.BoxExtent);
381		}
382	}
383	
384	void UGBPixelVfxComponent::EndPlay(const EEndPlayReason::Type EndPlayReason)
385	{
386		Stop();
387		Super::EndPlay(EndPlayReason);
388	}
389	
390	void UGBPixelVfxComponent::OnComponentDestroyed(bool bDestroyingHierarchy)
391	{
392		Stop();
393		Super::OnComponentDestroyed(bDestroyingHierarchy);
394	}
