133	void AGBPixelVfxBakeGameMode::BuildStage(const FString& MaterialPath)
134	{
135		using namespace GBPixelVfxStageLocal;
136		UWorld* World = GetWorld();
137		if (!World)
138		{
139			return;
140		}
141		DestroyStage();
142		// The stage runs along world Y: clips at X = 0, the back wall at X = +500,
143		// the camera at X = -1400 looking +X.
144		AddBox(World, StageActors, MaterialPath, FVector(0.f, 0.f, -50.f), FVector(30.f, 20.f, 1.f),
145			FLinearColor(0.02f, 0.02f, 0.025f), 0.15f, 0.f);
146		// Back wall, matte grey.
147		AddBox(World, StageActors, MaterialPath, FVector(500.f, 0.f, 600.f), FVector(1.f, 24.f, 14.f),
148			FLinearColor(0.18f, 0.18f, 0.19f), 0.7f, 0.f);
149		// Occluders between the clips and the wall, plus a few beside the clips, so the
150		// clip lights throw visible shadows. Heights 80 to 250 cm.
151		const float ObstacleHeights[4] = { 120.f, 200.f, 80.f, 250.f };
152		for (int32 i = 0; i < 4; ++i)
153		{
154			const float H = ObstacleHeights[i];
155			const float Y = -900.f + i * 600.f + 300.f;
156			if (i % 2 == 0)
157			{
158				AddBox(World, StageActors, MaterialPath, FVector(250.f, Y, H * 0.5f),
159					FVector(H / 100.f, H / 100.f, H / 100.f),
160					FLinearColor(0.1f, 0.1f, 0.11f), 0.6f, 0.f);
161			}
162			else
163			{
164				AddCylinder(World, StageActors, MaterialPath, FVector(250.f, Y, H * 0.5f),
165					H * 0.5f, H, FLinearColor(0.1f, 0.1f, 0.11f), 0.6f);
166			}
167		}
168		AddCylinder(World, StageActors, MaterialPath, FVector(-200.f, -600.f, 50.f),
169			60.f, 100.f, FLinearColor(0.1f, 0.1f, 0.11f), 0.6f);
170		AddBox(World, StageActors, MaterialPath, FVector(-200.f, 600.f, 90.f),
171			FVector(1.8f, 1.8f, 1.8f), FLinearColor(0.1f, 0.1f, 0.11f), 0.6f, 0.f);
172		// One very dim directional fill so the stage is readable but the clip lights dominate.
173		// The fill never casts shadows: the clip lights are the ones that must cast.
174		FActorSpawnParameters Params;
175		Params.SpawnCollisionHandlingOverride = ESpawnActorCollisionHandlingMethod::AlwaysSpawn;
176		ADirectionalLight* Dim = World->SpawnActor<ADirectionalLight>(ADirectionalLight::StaticClass(),
177			FTransform::Identity, Params);
178		if (Dim)
179		{
180			if (UDirectionalLightComponent* LightComp = Cast<UDirectionalLightComponent>(Dim->GetLightComponent()))
181			{
182				LightComp->SetMobility(EComponentMobility::Movable);
183				LightComp->SetIntensity(0.3f);
184				LightComp->SetLightColor(FLinearColor(0.8f, 0.85f, 1.f));
185				LightComp->SetCastShadows(false);
186				LightComp->SetUseRayTracedDistanceFieldShadows(false);
187			}
188			Dim->SetActorRotation(FRotator(-50.f, 20.f, 0.f));
189			StageActors.Add(Dim);
190		}
191		// Stage camera with its final wide transform in the spawn call.
192		const FVector WideFrom(-1400.f, 0.f, 350.f);
193		const FVector WideAt(0.f, 0.f, 180.f);
194		const FRotator WideRot = (WideAt - WideFrom).Rotation();
195		StageCam = World->SpawnActor<ACameraActor>(ACameraActor::StaticClass(),
196			FTransform(WideRot, WideFrom), Params);
197		StagePC = EnsurePlayerController();
198		if (StageCam)
199		{
200			StageCam->GetCameraComponent()->ProjectionMode = ECameraProjectionMode::Perspective;
201			StageCam->GetCameraComponent()->FieldOfView = 60.f;
202			// Fixed exposure so dark scenes are not auto-exposed: auto metering pinned to a
203			// single value (min == max, the engine's "fake manual exposure") plus a bias.
204			// NOTE: AEM_Manual was tried first (as specified) but couples to the physical
205			// camera defaults and underexposed the stage ~10 stops in -game; pinned auto
206			// delivers the required fixed exposure. Bloom stays default.
207			FPostProcessSettings& PP = StageCam->GetCameraComponent()->PostProcessSettings;
208			PP.bOverride_AutoExposureMethod = true;
209			PP.AutoExposureMethod = EAutoExposureMethod::AEM_Basic;
210			PP.bOverride_AutoExposureMinBrightness = true;
211			PP.AutoExposureMinBrightness = 1.0f;
212			PP.bOverride_AutoExposureMaxBrightness = true;
213			PP.AutoExposureMaxBrightness = 1.0f;
214			PP.bOverride_AutoExposureBias = true;
215			PP.AutoExposureBias = 1.0f;
216		}
217		if (StagePC && StageCam)
218		{
219			StagePC->SetViewTargetWithBlend(StageCam, 0.f);
220		}
221	}
