246	void AGBPixelVfxBakeGameMode::TickShowcase()
247	{
248		UWorld* World = GetWorld();
249		if (!World)
250		{
251			return;
252		}
253		FApp::SetUseFixedTimeStep(false);
254		switch (StageStep)
255		{
256		case 0:
257		{
258			BuildStage(FString(GBPixelVfxStageLocal::StageMaterialPath));
259			UGBPixelVfxSubsystem* Subsystem = World->GetGameInstance()
260				? World->GetGameInstance()->GetSubsystem<UGBPixelVfxSubsystem>()
261				: nullptr;
262			StageClipIds = Subsystem ? Subsystem->ListClipIds() : TArray<FName>();
263			if (StageClipIds.Num() == 0)
264			{
265				UE_LOG(LogGBPixelVfx, Error, TEXT("PVFX showcase: no baked clips found."));
266				FinishRun();
267				return;
268			}
269			const float StepY = 600.f;
270			const float Y0 = -(StageClipIds.Num() - 1) * StepY * 0.5f;
271			int32 SpawnedCount = 0;
272			int32 PlayingCount = 0;
273			for (int32 i = 0; i < StageClipIds.Num(); ++i)
274			{
275				AGBPixelVfxActor* Spawned = AGBPixelVfxActor::SpawnPixelVfx(
276					this, StageClipIds[i], FTransform(FVector(0.f, Y0 + i * StepY, 0.f)), 1.f);
277				if (Spawned)
278				{
279					++SpawnedCount;
280					Spawned->PixelVfx->bAutoDestroyOwnerWhenFinished = false;
281					if (Spawned->PixelVfx->IsPlaying())
282					{
283						++PlayingCount;
284					}
285				}
286				StageClips.Add(Spawned);
287			}
288			AActor* ViewTarget = StagePC ? StagePC->GetViewTarget() : nullptr;
289			UE_LOG(LogGBPixelVfx, Display, TEXT("PVFX showcase cam=%s rot=%s viewtarget=%s clips=%d spawned=%d playing=%d"),
290				StageCam ? *StageCam->GetActorLocation().ToCompactString() : TEXT("none"),
291				StageCam ? *StageCam->GetActorRotation().ToCompactString() : TEXT("none"),
292				ViewTarget ? *ViewTarget->GetName() : TEXT("none"),
293				StageClipIds.Num(), SpawnedCount, PlayingCount);
294			StageTimeMark = FPlatformTime::Seconds();
295			StageStep = 1;
296			break;
297		}
298		case 1:
299		{
300			// One-shots are re-spawned when they finish.
301			const float StepY = 600.f;
302			const float Y0 = -(StageClipIds.Num() - 1) * StepY * 0.5f;
303			for (int32 i = 0; i < StageClips.Num(); ++i)
304			{
305				AGBPixelVfxActor* Actor = StageClips[i].Get();
306				if (!Actor || !Actor->PixelVfx || !Actor->PixelVfx->IsPlaying())
307				{
308					if (Actor)
309					{
310						Actor->Destroy();
311					}
312					AGBPixelVfxActor* Spawned = AGBPixelVfxActor::SpawnPixelVfx(
313						this, StageClipIds[i], FTransform(FVector(0.f, Y0 + i * StepY, 0.f)), 1.f);
314					if (Spawned)
315					{
316						Spawned->PixelVfx->bAutoDestroyOwnerWhenFinished = false;
317						StageClips[i] = Spawned;
318					}
319				}
320			}
321			if (FPlatformTime::Seconds() - StageTimeMark >= 2.0)
322			{
323				const FString Dir = FPaths::ProjectSavedDir() / TEXT("PixelVfx/Showcase");
324				TakeStageScreenshot(Dir / TEXT("showcase_1.png"));
325				StageTimeMark = FPlatformTime::Seconds();
326				StageWait = 15;
327				StageStep = 2;
328			}
329			break;
330		}
331		case 2:
332			if (--StageWait <= 0 && FPlatformTime::Seconds() - StageTimeMark >= 0.7)
333			{
334				const FString Dir = FPaths::ProjectSavedDir() / TEXT("PixelVfx/Showcase");
335				TakeStageScreenshot(Dir / TEXT("showcase_2.png"));
336				StageShotIndex = 0;
337				StageWait = 15;
338				StageStep = 3;
339			}
340			break;
341		case 3:
342			if (--StageWait <= 0)
343			{
344				if (StageShotIndex >= StageClipIds.Num())
345				{
346					const FString Dir = FPaths::ProjectSavedDir() / TEXT("PixelVfx/Showcase");
347					UE_LOG(LogGBPixelVfx, Display, TEXT("PVFX SHOWCASE: %d clips, screenshots in %s."),
348						StageClipIds.Num(), *Dir);
349					FinishRun();
350					return;
351				}
352				// One-shots may have finished while earlier close-ups were taken: re-spawn.
353				// (Conditional: loops keep playing so their animation continues.)
354				const float StepY = 600.f;
355				const float Y0 = -(StageClipIds.Num() - 1) * StepY * 0.5f;
356				const FVector ClipAt(0.f, Y0 + StageShotIndex * StepY, 0.f);
357				AGBPixelVfxActor* ShotActor = StageClips[StageShotIndex].Get();
358				if (!ShotActor || !ShotActor->PixelVfx || !ShotActor->PixelVfx->IsPlaying())
359				{
360					if (ShotActor)
361					{
362						ShotActor->Destroy();
363					}
364					AGBPixelVfxActor* Spawned = AGBPixelVfxActor::SpawnPixelVfx(
365						this, StageClipIds[StageShotIndex], FTransform(ClipAt), 1.f);
366					if (Spawned)
367					{
368						Spawned->PixelVfx->bAutoDestroyOwnerWhenFinished = false;
369						StageClips[StageShotIndex] = Spawned;
370					}
371				}
372				// Close-up framing WITHOUT translating the camera (rotate in place and
373				// narrow the FOV instead): translating the stage camera breaks quad
374				// rendering in -game here, while rotating in place does not. This
375				// deviates from "600 cm in front" (see report); the framing still shows
376				// each sprite large, upright and with its base visible.
377				if (StageCam)
378				{
379					const FVector ToClip = FVector(ClipAt.X, ClipAt.Y, 200.f) - StageCam->GetActorLocation();
380					StageCam->SetActorRotation(ToClip.Rotation());
381					StageCam->GetCameraComponent()->SetFieldOfView(15.f);
382				}
383				StageTimeMark = FPlatformTime::Seconds();
384				StageStep = 4;
385			}
386			break;
387		case 4:
388			if (FPlatformTime::Seconds() - StageTimeMark >= 1.0)
389			{
390				const FString Dir = FPaths::ProjectSavedDir() / TEXT("PixelVfx/Showcase");
391				TakeStageScreenshot(Dir / (TEXT("showcase_") + StageClipIds[StageShotIndex].ToString() + TEXT(".png")));
392				++StageShotIndex;
393				StageWait = 15;
394				StageStep = 3;
395			}
396			break;
397		default:
398			break;
399		}
400	}
401	
402	// ---- compare mode ----
403	
404	void AGBPixelVfxBakeGameMode::CmpClearActors()
405	{
406		for (const TObjectPtr<AActor>& Actor : CmpActors)
407		{
408			if (Actor)
409			{
410				Actor->Destroy();
411			}
412		}
413		CmpActors.Reset();
414	}
415	
416	void AGBPixelVfxBakeGameMode::CmpSpawnSourceGrid()
417	{
418		UWorld* World = GetWorld();
419		UNiagaraSystem* System = LoadObject<UNiagaraSystem>(nullptr, *CmpJob.SystemPath);
420		if (!World || !System)
421		{
422			return;
423		}
424		FActorSpawnParameters Params;
425		Params.SpawnCollisionHandlingOverride = ESpawnActorCollisionHandlingMethod::AlwaysSpawn;
426		for (int32 iy = 0; iy < 2; ++iy)
427		{
428			for (int32 ix = 0; ix < 4; ++ix)
429			{
430				const FVector At(-150.f + iy * 300.f, -600.f + ix * 400.f, 0.f);
431				AActor* Actor = World->SpawnActor<AActor>(AActor::StaticClass(), FTransform(At), Params);
432				if (!Actor)
433				{
434					continue;
435				}
436				UNiagaraComponent* Comp = NewObject<UNiagaraComponent>(Actor, NAME_None, RF_Transient);
437				Actor->SetRootComponent(Comp);
438				Comp->RegisterComponent();
439				Comp->SetAsset(System);
440				Comp->SetRandomSeedOffset(ix + iy * 4);
441				Comp->SetAllowScalability(false);
442				Comp->Activate(true);
443				CmpActors.Add(Actor);
444			}
445		}
446	}
447	
448	void AGBPixelVfxBakeGameMode::CmpSpawnBakedGrid()
449	{
450		for (int32 iy = 0; iy < 2; ++iy)
451		{
452			for (int32 ix = 0; ix < 4; ++ix)
453			{
454				const FVector At(-150.f + iy * 300.f, -600.f + ix * 400.f, 0.f);
455				if (AGBPixelVfxActor* Actor = AGBPixelVfxActor::SpawnPixelVfx(this, CmpJob.Id, FTransform(At), 1.f))
456				{
457					Actor->PixelVfx->bAutoDestroyOwnerWhenFinished = false;
458					CmpActors.Add(Actor);
459				}
460			}
461		}
462	}
463	
464	void AGBPixelVfxBakeGameMode::CmpWriteResults()
465	{
466		const FString Dir = FPaths::ProjectSavedDir() / TEXT("PixelVfx") / CmpJob.Id.ToString();
467		IPlatformFile& Files = FPlatformFileManager::Get().GetPlatformFile();
468		Files.CreateDirectoryTree(*Dir);
469		UE_LOG(LogGBPixelVfx, Display,
470			TEXT("PVFX COMPARE %s: x8 source frame=%.1f ms gpu=%.1f ms | x8 baked frame=%.1f ms gpu=%.1f ms | empty frame=%.1f ms gpu=%.1f ms"),
471			*CmpJob.Id.ToString(), CmpSourceFrameMs, CmpSourceGpuMs,
472			CmpBakedFrameMs, CmpBakedGpuMs, CmpEmptyFrameMs, CmpEmptyGpuMs);
473		const FString Json = FString::Printf(
474			TEXT("{\"Id\":\"%s\",\"SourceFrameMs\":%.2f,\"SourceGpuMs\":%.2f,\"BakedFrameMs\":%.2f,\"BakedGpuMs\":%.2f,\"EmptyFrameMs\":%.2f,\"EmptyGpuMs\":%.2f}"),
475			*CmpJob.Id.ToString(), CmpSourceFrameMs, CmpSourceGpuMs,
476			CmpBakedFrameMs, CmpBakedGpuMs, CmpEmptyFrameMs, CmpEmptyGpuMs);
477		FFileHelper::SaveStringToFile(Json, *(Dir / TEXT("compare.json")));
478	}
479	
480	void AGBPixelVfxBakeGameMode::TickCompare()
481	{
482		UWorld* World = GetWorld();
483		if (!World)
484		{
485			return;
486		}
487		FApp::SetUseFixedTimeStep(false);
488		switch (StageStep)
489		{
490		case 0:
491		{
492			if (!CmpJob.LoadFromFile(FPaths::ProjectPluginsDir() / TEXT("GBPixelVfx/Bake/Jobs") / (RunArg + TEXT(".json"))))
493			{
494				UE_LOG(LogGBPixelVfx, Error, TEXT("PVFX compare: cannot read job '%s'."), *RunArg);
495				FinishRun();
496				return;
497			}
498			if (GEngine)
499			{
500				GEngine->Exec(World, TEXT("t.MaxFPS 0"));
501				GEngine->Exec(World, TEXT("r.VSync 0"));
502			}
503			BuildStage(FString(GBPixelVfxStageLocal::StageMaterialPath));
504			AActor* ViewTarget = StagePC ? StagePC->GetViewTarget() : nullptr;
505			UE_LOG(LogGBPixelVfx, Display, TEXT("PVFX compare cam=%s viewtarget=%s job=%s"),
506				StageCam ? *StageCam->GetActorLocation().ToCompactString() : TEXT("none"),
507				ViewTarget ? *ViewTarget->GetName() : TEXT("none"), *CmpJob.Id.ToString());
508			// Phase 0: the source system and the baked clip side by side, 500 cm apart.
509			UNiagaraSystem* System = LoadObject<UNiagaraSystem>(nullptr, *CmpJob.SystemPath);
510			if (!System)
511			{
512				UE_LOG(LogGBPixelVfx, Error, TEXT("PVFX compare: cannot load system '%s'."), *CmpJob.SystemPath);
513				FinishRun();
514				return;
515			}
516			FActorSpawnParameters Params;
517			Params.SpawnCollisionHandlingOverride = ESpawnActorCollisionHandlingMethod::AlwaysSpawn;
518			if (AActor* Actor = World->SpawnActor<AActor>(AActor::StaticClass(), FTransform(FVector(0.f, -250.f, 0.f)), Params))
519			{
520				UNiagaraComponent* Comp = NewObject<UNiagaraComponent>(Actor, NAME_None, RF_Transient);
521				Actor->SetRootComponent(Comp);
522				Comp->RegisterComponent();
523				Comp->SetAsset(System);
524				Comp->SetRandomSeedOffset(0);
525				Comp->SetAllowScalability(false);
526				Comp->Activate(true);
527				CmpActors.Add(Actor);
528			}
529			if (AGBPixelVfxActor* Baked = AGBPixelVfxActor::SpawnPixelVfx(this, CmpJob.Id, FTransform(FVector(0.f, 250.f, 0.f)), 1.f))
530			{
531				Baked->PixelVfx->bAutoDestroyOwnerWhenFinished = false;
532				CmpActors.Add(Baked);
533			}
534			StageTimeMark = FPlatformTime::Seconds();
535			StageStep = 1;
536			break;
537		}
538		case 1:
539			// Warm-up plus one second, then the side-by-side screenshot.
540			if (FPlatformTime::Seconds() - StageTimeMark >= CmpJob.WarmupSeconds + 1.0)
541			{
542				// The timing numbers are only valid if the source simulation runs: log its state.
543				int32 SourceActive = 0;
544				float SourceAge = -1.f;
545				for (const TObjectPtr<AActor>& Actor : CmpActors)
546				{
547					if (UNiagaraComponent* Comp = Actor ? Actor->FindComponentByClass<UNiagaraComponent>() : nullptr)
548					{
549						SourceActive = Comp->IsActive() ? 1 : 0;
550						if (Comp->GetSystemInstanceController().IsValid())
551						{
552							SourceAge = Comp->GetSystemInstanceController()->GetAge();
553						}
554					}
555				}
556				int32 BakedPlaying = 0;
557				for (const TObjectPtr<AActor>& Actor : CmpActors)
558				{
559					if (AGBPixelVfxActor* Baked = Cast<AGBPixelVfxActor>(Actor))
560					{
561						if (Baked->PixelVfx && Baked->PixelVfx->IsPlaying())
562						{
563							BakedPlaying = 1;
564						}
565					}
566				}
567				UE_LOG(LogGBPixelVfx, Display, TEXT("PVFX compare diag: source active=%d age=%.1f baked playing=%d"),
568					SourceActive, SourceAge, BakedPlaying);
569				const FString Dir = FPaths::ProjectSavedDir() / TEXT("PixelVfx") / CmpJob.Id.ToString();
570				TakeStageScreenshot(Dir / TEXT("compare.png"));
571				StageWait = 15;
572				StageTimeMark = FPlatformTime::Seconds();
573				StageStep = 2;
574			}
575			break;
576		case 2:
577			if (--StageWait <= 0)
578			{
579				CmpClearActors();
580				CmpSpawnSourceGrid();
581				StageTimeMark = FPlatformTime::Seconds();
582				StageStep = 3;
583			}
584			break;
585		case 3:
586			// Let 8 source systems run for 3 s, then measure 180 frames.
587			if (FPlatformTime::Seconds() - StageTimeMark >= 3.0)
588			{
589				CmpMeasureLeft = 180;
590				CmpCpuSum = 0.0;
591				CmpGpuSum = 0.0;
592				CmpCpuCount = 0;
593				CmpPrevNow = FPlatformTime::Seconds();
594				CmpPrevGpu = RHIGetGPUFrameCycles();
595				StageStep = 4;
596			}
597			break;
598		case 4:
599		{
600			const double Now = FPlatformTime::Seconds();
601			const double Dt = (Now - CmpPrevNow) * 1000.0;
602			CmpPrevNow = Now;
603			// RHIGetGPUFrameCycles returns the last measured GPU frame cost already in
604			// CPU-cycle units (see FRHIGPUFrameTimeHistory::PushFrameCycles), so each
605			// sample converts directly; no delta against the previous sample.
606			CmpGpuSum += FPlatformTime::ToMilliseconds(RHIGetGPUFrameCycles());
607			CmpCpuSum += Dt;
608			++CmpCpuCount;
609			if (--CmpMeasureLeft <= 0)
610			{
611				CmpSourceFrameMs = CmpCpuSum / FMath::Max(1, CmpCpuCount);
612				CmpSourceGpuMs = CmpGpuSum / FMath::Max(1, CmpCpuCount);
613				CmpClearActors();
614				CmpSpawnBakedGrid();
615				StageTimeMark = FPlatformTime::Seconds();
616				StageStep = 5;
617			}
618			break;
619		}
620		case 5:
621			// Baked population settles for 1 s (one-shots restart when they finish, lights included).
622			for (const TObjectPtr<AActor>& Actor : CmpActors)
623			{
624				if (AGBPixelVfxActor* Baked = Cast<AGBPixelVfxActor>(Actor))
625				{
626					if (Baked->PixelVfx && !Baked->PixelVfx->IsPlaying())
627					{
628						Baked->PixelVfx->Play(CmpJob.Id, true);
629					}
630				}
631			}
632			if (FPlatformTime::Seconds() - StageTimeMark >= 1.0)
633			{
634				CmpMeasureLeft = 180;
635				CmpCpuSum = 0.0;
636				CmpGpuSum = 0.0;
637				CmpCpuCount = 0;
638				CmpPrevNow = FPlatformTime::Seconds();
639				CmpPrevGpu = RHIGetGPUFrameCycles();
640				StageStep = 6;
641			}
642			break;
643		case 6:
644		{
645			for (const TObjectPtr<AActor>& Actor : CmpActors)
646			{
647				if (AGBPixelVfxActor* Baked = Cast<AGBPixelVfxActor>(Actor))
648				{
649					if (Baked->PixelVfx && !Baked->PixelVfx->IsPlaying())
650					{
651						Baked->PixelVfx->Play(CmpJob.Id, true);
652					}
653				}
654			}
655			const double Now = FPlatformTime::Seconds();
656			const double Dt = (Now - CmpPrevNow) * 1000.0;
657			CmpPrevNow = Now;
658			CmpGpuSum += FPlatformTime::ToMilliseconds(RHIGetGPUFrameCycles());
659			CmpCpuSum += Dt;
660			++CmpCpuCount;
661			if (--CmpMeasureLeft <= 0)
662			{
663				CmpBakedFrameMs = CmpCpuSum / FMath::Max(1, CmpCpuCount);
664				CmpBakedGpuMs = CmpGpuSum / FMath::Max(1, CmpCpuCount);
665				CmpClearActors();
666				StageTimeMark = FPlatformTime::Seconds();
667				StageStep = 7;
668			}
669			break;
670		}
671		case 7:
672			if (FPlatformTime::Seconds() - StageTimeMark >= 1.0)
673			{
674				CmpMeasureLeft = 180;
675				CmpCpuSum = 0.0;
676				CmpGpuSum = 0.0;
677				CmpCpuCount = 0;
678				CmpPrevNow = FPlatformTime::Seconds();
679				CmpPrevGpu = RHIGetGPUFrameCycles();
680				StageStep = 8;
681			}
682			break;
683		case 8:
684		{
685			const double Now = FPlatformTime::Seconds();
686			const double Dt = (Now - CmpPrevNow) * 1000.0;
687			CmpPrevNow = Now;
688			CmpGpuSum += FPlatformTime::ToMilliseconds(RHIGetGPUFrameCycles());
689			CmpCpuSum += Dt;
690			++CmpCpuCount;
691			if (--CmpMeasureLeft <= 0)
692			{
693				CmpEmptyFrameMs = CmpCpuSum / FMath::Max(1, CmpCpuCount);
694				CmpEmptyGpuMs = CmpGpuSum / FMath::Max(1, CmpCpuCount);
695				CmpWriteResults();
696				FinishRun();
697			}
698			break;
699		}
700		default:
701			break;
702		}
703	}
