34		const TCHAR* CylinderPath = TEXT("/Engine/BasicShapes/Cylinder.Cylinder");
35	
36		void AddBox(UWorld* World, TArray<TObjectPtr<AActor>>& Out, const FString& BasePath,
37			const FVector& Pos, const FVector& Scale, const FLinearColor& Color, float Roughness, float Metallic)
38		{
39			if (!World)
40			{
41				return;
42			}
43			UStaticMesh* Cube = Cast<UStaticMesh>(StaticLoadObject(UStaticMesh::StaticClass(), nullptr, CubePath));
44			UMaterialInterface* Base = Cast<UMaterialInterface>(StaticLoadObject(UMaterialInterface::StaticClass(),
45				nullptr, *BasePath));
46			if (!Cube || !Base)
47			{
48				return;
49			}
50			FActorSpawnParameters Params;
51			Params.SpawnCollisionHandlingOverride = ESpawnActorCollisionHandlingMethod::AlwaysSpawn;
52			AActor* Actor = World->SpawnActor<AActor>(AActor::StaticClass(), FTransform(Pos), Params);
53			if (!Actor)
54			{
55				return;
56			}
57			UStaticMeshComponent* Mesh = NewObject<UStaticMeshComponent>(Actor, NAME_None, RF_Transient);
58			Mesh->SetMobility(EComponentMobility::Movable);
59			Actor->SetRootComponent(Mesh);
60			Mesh->SetStaticMesh(Cube);
61			Mesh->SetRelativeScale3D(Scale);
62			Mesh->SetCollisionEnabled(ECollisionEnabled::NoCollision);
63			Mesh->RegisterComponent();
64			UMaterialInstanceDynamic* Dyn = UMaterialInstanceDynamic::Create(Base, Actor);
65			Dyn->SetVectorParameterValue(TEXT("Color"), Color);
66			Dyn->SetScalarParameterValue(TEXT("Roughness"), Roughness);
67			Dyn->SetScalarParameterValue(TEXT("Metallic"), Metallic);
68			Mesh->SetMaterial(0, Dyn);
69			Out.Add(Actor);
70		}
71	
72		void AddCylinder(UWorld* World, TArray<TObjectPtr<AActor>>& Out, const FString& BasePath,
73			const FVector& Pos, float RadiusCm, float HeightCm, const FLinearColor& Color, float Roughness)
74		{
75			if (!World)
76			{
77				return;
78			}
79			UStaticMesh* Cylinder = Cast<UStaticMesh>(StaticLoadObject(UStaticMesh::StaticClass(), nullptr, CylinderPath));
80			UMaterialInterface* Base = Cast<UMaterialInterface>(StaticLoadObject(UMaterialInterface::StaticClass(),
81				nullptr, *BasePath));
82			if (!Cylinder || !Base)
83			{
84				return;
85			}
86			FActorSpawnParameters Params;
87			Params.SpawnCollisionHandlingOverride = ESpawnActorCollisionHandlingMethod::AlwaysSpawn;
88			AActor* Actor = World->SpawnActor<AActor>(AActor::StaticClass(), FTransform(Pos), Params);
89			if (!Actor)
90			{
91				return;
92			}
93			UStaticMeshComponent* Mesh = NewObject<UStaticMeshComponent>(Actor, NAME_None, RF_Transient);
94			Mesh->SetMobility(EComponentMobility::Movable);
95			Actor->SetRootComponent(Mesh);
96			Mesh->SetStaticMesh(Cylinder);
97			// The engine cylinder is 100 cm across and 100 cm tall.
98			Mesh->SetRelativeScale3D(FVector(RadiusCm * 2.f / 100.f, RadiusCm * 2.f / 100.f, HeightCm / 100.f));
99			Mesh->SetCollisionEnabled(ECollisionEnabled::NoCollision);
100			Mesh->RegisterComponent();
101			UMaterialInstanceDynamic* Dyn = UMaterialInstanceDynamic::Create(Base, Actor);
102			Dyn->SetVectorParameterValue(TEXT("Color"), Color);
103			Dyn->SetScalarParameterValue(TEXT("Roughness"), Roughness);
104			Dyn->SetScalarParameterValue(TEXT("Metallic"), 0.f);
105			Mesh->SetMaterial(0, Dyn);
106			Out.Add(Actor);
107		}
