245	
246	void AGBPixelVfxBakeGameMode::TickShowcase()
247	{
248		UWorld* World = GetWorld();
249		if (!World)
250		{
251			return;
252		}
253		FApp::SetUseFixedTimeStep(false);
254		switch (StageStep)
255		{
256		case 0:
257		{
258			BuildStage(FString(GBPixelVfxStageLocal::StageMaterialPath));
259			UGBPixelVfxSubsystem* Subsystem = World->GetGameInstance()
260				? World->GetGameInstance()->GetSubsystem<UGBPixelVfxSubsystem>()
261				: nullptr;
262			StageClipIds = Subsystem ? Subsystem->ListClipIds() : TArray<FName>();
263			if (StageClipIds.Num() == 0)
264			{
265				UE_LOG(LogGBPixelVfx, Error, TEXT("PVFX showcase: no baked clips found."));
266				FinishRun();
267				return;
268			}
269			const float StepY = 600.f;
270			const float Y0 = -(StageClipIds.Num() - 1) * StepY * 0.5f;
271			int32 SpawnedCount = 0;
272			int32 PlayingCount = 0;
273			for (int32 i = 0; i < StageClipIds.Num(); ++i)
274			{
275				AGBPixelVfxActor* Spawned = AGBPixelVfxActor::SpawnPixelVfx(
276					this, StageClipIds[i], FTransform(FVector(0.f, Y0 + i * StepY, 0.f)), 1.f);
277				if (Spawned)
278				{
279					++SpawnedCount;
280					Spawned->PixelVfx->bAutoDestroyOwnerWhenFinished = false;
281					if (Spawned->PixelVfx->IsPlaying())
282					{
283						++PlayingCount;
284					}
285				}
286				StageClips.Add(Spawned);
287			}
288			AActor* ViewTarget = StagePC ? StagePC->GetViewTarget() : nullptr;
289			UE_LOG(LogGBPixelVfx, Display, TEXT("PVFX showcase cam=%s rot=%s viewtarget=%s clips=%d spawned=%d playing=%d"),
290				StageCam ? *StageCam->GetActorLocation().ToCompactString() : TEXT("none"),
291				StageCam ? *StageCam->GetActorRotation().ToCompactString() : TEXT("none"),
292				ViewTarget ? *ViewTarget->GetName() : TEXT("none"),
293				StageClipIds.Num(), SpawnedCount, PlayingCount);
294			StageTimeMark = FPlatformTime::Seconds();
295			StageStep = 1;
296			break;
297		}
298		case 1:
299		{
300			// One-shots are re-spawned when they finish.
301			const float StepY = 600.f;
302			const float Y0 = -(StageClipIds.Num() - 1) * StepY * 0.5f;
303			for (int32 i = 0; i < StageClips.Num(); ++i)
304			{
305				AGBPixelVfxActor* Actor = StageClips[i].Get();
306				if (!Actor || !Actor->PixelVfx || !Actor->PixelVfx->IsPlaying())
307				{
308					if (Actor)
309					{
310						Actor->Destroy();
311					}
312					AGBPixelVfxActor* Spawned = AGBPixelVfxActor::SpawnPixelVfx(
313						this, StageClipIds[i], FTransform(FVector(0.f, Y0 + i * StepY, 0.f)), 1.f);
314					if (Spawned)
315					{
316						Spawned->PixelVfx->bAutoDestroyOwnerWhenFinished = false;
317						StageClips[i] = Spawned;
318					}
319				}
320			}
321			if (FPlatformTime::Seconds() - StageTimeMark >= 2.0)
322			{
323				const FString Dir = FPaths::ProjectSavedDir() / TEXT("PixelVfx/Showcase");
324				TakeStageScreenshot(Dir / TEXT("showcase_1.png"));
325				StageTimeMark = FPlatformTime::Seconds();
326				StageWait = 15;
327				StageStep = 2;
328			}
329			break;
330		}
331		case 2:
332			if (--StageWait <= 0 && FPlatformTime::Seconds() - StageTimeMark >= 0.7)
333			{
334				const FString Dir = FPaths::ProjectSavedDir() / TEXT("PixelVfx/Showcase");
335				TakeStageScreenshot(Dir / TEXT("showcase_2.png"));
336				StageShotIndex = 0;
337				StageWait = 15;
338				StageStep = 3;
339			}
340			break;
341		case 3:
342			if (--StageWait <= 0)
343			{
344				if (StageShotIndex >= StageClipIds.Num())
345				{
346					const FString Dir = FPaths::ProjectSavedDir() / TEXT("PixelVfx/Showcase");
347					UE_LOG(LogGBPixelVfx, Display, TEXT("PVFX SHOWCASE: %d clips, screenshots in %s."),
348						StageClipIds.Num(), *Dir);
349					FinishRun();
350					return;
351				}
352				// One-shots may have finished while earlier close-ups were taken: re-spawn.
353				// (Conditional: loops keep playing so their animation continues.)
354				const float StepY = 600.f;
355				const float Y0 = -(StageClipIds.Num() - 1) * StepY * 0.5f;
356				const FVector ClipAt(0.f, Y0 + StageShotIndex * StepY, 0.f);
357				AGBPixelVfxActor* ShotActor = StageClips[StageShotIndex].Get();
358				if (!ShotActor || !ShotActor->PixelVfx || !ShotActor->PixelVfx->IsPlaying())
359				{
360					if (ShotActor)
361					{
362						ShotActor->Destroy();
363					}
364					AGBPixelVfxActor* Spawned = AGBPixelVfxActor::SpawnPixelVfx(
365						this, StageClipIds[StageShotIndex], FTransform(ClipAt), 1.f);
366					if (Spawned)
367					{
368						Spawned->PixelVfx->bAutoDestroyOwnerWhenFinished = false;
369						StageClips[StageShotIndex] = Spawned;
370					}
371				}
372				// Close-up framing WITHOUT translating the camera (rotate in place and
373				// narrow the FOV instead): translating the stage camera breaks quad
374				// rendering in -game here, while rotating in place does not. This
375				// deviates from "600 cm in front" (see report); the framing still shows
376				// each sprite large, upright and with its base visible.
377				if (StageCam)
378				{
379					const FVector ToClip = FVector(ClipAt.X, ClipAt.Y, 200.f) - StageCam->GetActorLocation();
380					StageCam->SetActorRotation(ToClip.Rotation());
381					StageCam->GetCameraComponent()->SetFieldOfView(15.f);
382				}
383				StageTimeMark = FPlatformTime::Seconds();
384				StageStep = 4;
385			}
386			break;
387		case 4:
388			if (FPlatformTime::Seconds() - StageTimeMark >= 1.0)
389			{
390				const FString Dir = FPaths::ProjectSavedDir() / TEXT("PixelVfx/Showcase");
391				TakeStageScreenshot(Dir / (TEXT("showcase_") + StageClipIds[StageShotIndex].ToString() + TEXT(".png")));
392				++StageShotIndex;
393				StageWait = 15;
394				StageStep = 3;
395			}
396			break;
397		default:
398			break;
399		}
400	}
