416	void AGBPixelVfxBakeGameMode::CmpSpawnSourceGrid()
417	{
418		UWorld* World = GetWorld();
419		UNiagaraSystem* System = LoadObject<UNiagaraSystem>(nullptr, *CmpJob.SystemPath);
420		if (!World || !System)
421		{
422			return;
423		}
424		FActorSpawnParameters Params;
425		Params.SpawnCollisionHandlingOverride = ESpawnActorCollisionHandlingMethod::AlwaysSpawn;
426		for (int32 iy = 0; iy < 2; ++iy)
427		{
428			for (int32 ix = 0; ix < 4; ++ix)
429			{
430				const FVector At(-150.f + iy * 300.f, -600.f + ix * 400.f, 0.f);
431				AActor* Actor = World->SpawnActor<AActor>(AActor::StaticClass(), FTransform(At), Params);
432				if (!Actor)
433				{
434					continue;
435				}
436				UNiagaraComponent* Comp = NewObject<UNiagaraComponent>(Actor, NAME_None, RF_Transient);
437				Actor->SetRootComponent(Comp);
438				Comp->RegisterComponent();
439				Comp->SetAsset(System);
440				Comp->SetRandomSeedOffset(ix + iy * 4);
441				Comp->SetAllowScalability(false);
442				Comp->Activate(true);
443				CmpActors.Add(Actor);
444			}
445		}
446	}
