479	
480	void AGBPixelVfxBakeGameMode::TickCompare()
481	{
482		UWorld* World = GetWorld();
483		if (!World)
484		{
485			return;
486		}
487		FApp::SetUseFixedTimeStep(false);
488		switch (StageStep)
489		{
490		case 0:
491		{
492			if (!CmpJob.LoadFromFile(FPaths::ProjectPluginsDir() / TEXT("GBPixelVfx/Bake/Jobs") / (RunArg + TEXT(".json"))))
493			{
494				UE_LOG(LogGBPixelVfx, Error, TEXT("PVFX compare: cannot read job '%s'."), *RunArg);
495				FinishRun();
496				return;
497			}
498			if (GEngine)
499			{
500				GEngine->Exec(World, TEXT("t.MaxFPS 0"));
501				GEngine->Exec(World, TEXT("r.VSync 0"));
502			}
503			BuildStage(FString(GBPixelVfxStageLocal::StageMaterialPath));
504			AActor* ViewTarget = StagePC ? StagePC->GetViewTarget() : nullptr;
505			UE_LOG(LogGBPixelVfx, Display, TEXT("PVFX compare cam=%s viewtarget=%s job=%s"),
506				StageCam ? *StageCam->GetActorLocation().ToCompactString() : TEXT("none"),
507				ViewTarget ? *ViewTarget->GetName() : TEXT("none"), *CmpJob.Id.ToString());
508			// Phase 0: the source system and the baked clip side by side, 500 cm apart.
509			UNiagaraSystem* System = LoadObject<UNiagaraSystem>(nullptr, *CmpJob.SystemPath);
510			if (!System)
511			{
512				UE_LOG(LogGBPixelVfx, Error, TEXT("PVFX compare: cannot load system '%s'."), *CmpJob.SystemPath);
513				FinishRun();
514				return;
515			}
516			FActorSpawnParameters Params;
517			Params.SpawnCollisionHandlingOverride = ESpawnActorCollisionHandlingMethod::AlwaysSpawn;
518			if (AActor* Actor = World->SpawnActor<AActor>(AActor::StaticClass(), FTransform(FVector(0.f, -250.f, 0.f)), Params))
519			{
520				UNiagaraComponent* Comp = NewObject<UNiagaraComponent>(Actor, NAME_None, RF_Transient);
521				Actor->SetRootComponent(Comp);
522				Comp->RegisterComponent();
523				Comp->SetAsset(System);
524				Comp->SetRandomSeedOffset(0);
525				Comp->SetAllowScalability(false);
526				Comp->Activate(true);
527				CmpActors.Add(Actor);
528			}
529			if (AGBPixelVfxActor* Baked = AGBPixelVfxActor::SpawnPixelVfx(this, CmpJob.Id, FTransform(FVector(0.f, 250.f, 0.f)), 1.f))
530			{
531				Baked->PixelVfx->bAutoDestroyOwnerWhenFinished = false;
532				CmpActors.Add(Baked);
533			}
534			StageTimeMark = FPlatformTime::Seconds();
535			StageStep = 1;
536			break;
537		}
538		case 1:
539			// Warm-up plus one second, then the side-by-side screenshot.
540			if (FPlatformTime::Seconds() - StageTimeMark >= CmpJob.WarmupSeconds + 1.0)
541			{
542				// The timing numbers are only valid if the source simulation runs: log its state.
543				int32 SourceActive = 0;
544				float SourceAge = -1.f;
545				for (const TObjectPtr<AActor>& Actor : CmpActors)
546				{
547					if (UNiagaraComponent* Comp = Actor ? Actor->FindComponentByClass<UNiagaraComponent>() : nullptr)
548					{
549						SourceActive = Comp->IsActive() ? 1 : 0;
550						if (Comp->GetSystemInstanceController().IsValid())
551						{
552							SourceAge = Comp->GetSystemInstanceController()->GetAge();
553						}
