// One-off: my changes to two files another chat is editing at the same time (GBDevCommands.cpp, Glyphbound.Build.cs).
// Usage:
//   node pvfx_shared_files.js work            apply to the working files
//   node pvfx_shared_files.js stage           write "HEAD + my change" blobs to the git index (working files untouched),
//                                             so my commit carries my lines only and none of the other chat's unfinished work
const fs = require('fs');
const { execFileSync } = require('child_process');
const repo = 'C:/GameJam';
const L = (lines) => lines.join('\n') + '\n';

function rep(s, a, b, what) {
  const n = s.split(a).length - 1;
  if (n !== 1) { throw new Error('MISMATCH (' + n + ') ' + what + ': ' + a.slice(0, 70)); }
  return s.split(a).join(b);
}

function buildCs(s) {
  if (s.includes('"GBPixelVfx"')) return s;
  return rep(s, '\t\t});\n\t}\n}',
    '\t\t});\n\n' +
    '\t\t// Baked pixel VFX clips (Plugins/GBPixelVfx, Runtime module): the flame and the explosion of the Fireball.\n' +
    '\t\tPrivateDependencyModuleNames.Add("GBPixelVfx");\n\t}\n}', 'Build.cs end');
}

function devCommands(s) {
  if (s.includes('17_pixelvfx_fireball_flight')) return s;
  s = rep(s, 'Add(68.9f + S, TEXT("pixelvfx: screenshot of the baked fire lighting the room")',
    'Add(68.7f + S, TEXT("pixelvfx: screenshot of the baked fire lighting the room")', 'shot step time');
  const tail = '\t\t\tShot(TEXT("16_pixelvfx_fire"));\n\t\t}, 0.5f);\n';
  const added = L([
    '\t\t\tShot(TEXT("16_pixelvfx_fire"));',
    '\t\t}, 0.35f);',
    '\t\t// The Fireball carries the baked fire clip in flight and plays the baked explosion where it lands (Spells.json:',
    '\t\t// Strings FlightVfx / ImpactVfx). Aimed at the floor a few metres ahead so it lands inside this block.',
    '\t\tAdd(68.72f + S, TEXT("pixelvfx: aim at the floor a few metres ahead"), [](UWorld* World, AGBPlayerCharacter* Player)',
    '\t\t{',
    '\t\t\tSetQTEEnabled(false);',
    '\t\t\tPlayer->GetAttributes()->RestoreAll();',
    '\t\t\tif (AGBPlayerController* PC = Cast<AGBPlayerController>(Player->GetController()))',
    '\t\t\t{',
    '\t\t\t\tPC->SetControlRotation(FRotator(-15.f, PC->GetControlRotation().Yaw, 0.f));',
    '\t\t\t}',
    '\t\t\tMarkSim(World);',
    '\t\t});',
    '\t\tAdd(68.8f + S, TEXT("pixelvfx: cast the Fireball"), [](UWorld* World, AGBPlayerCharacter* Player)',
    '\t\t{',
    '\t\t\tconst bool bOk = Player->GetSpellbook()->TryCastSlot(0);',
    '\t\t\tMarkSim(World);',
    '\t\t\tUE_LOG(LogGB, Display, TEXT("SMOKE pixelvfx fireball cast ok=%d spell=%s"), bOk ? 1 : 0, *Player->GetSpellbook()->GetSlotSpell(0).ToString());',
    '\t\t}, 0.03f);',
    '\t\tAdd(68.9f + S, TEXT("pixelvfx: screenshot of the Fireball in flight"), [](UWorld* World, AGBPlayerCharacter*)',
    '\t\t{',
    '\t\t\tint32 Projectiles = 0;',
    '\t\t\tint32 WithClip = 0;',
    '\t\t\tfor (TActorIterator<AGBProjectile> It(World); It; ++It)',
    '\t\t\t{',
    '\t\t\t\t++Projectiles;',
    '\t\t\t\tWithClip += It->HasFlightVfx() ? 1 : 0;',
    '\t\t\t}',
    '\t\t\tUE_LOG(LogGB, Display, TEXT("SMOKE pixelvfx fireball flight projectiles=%d with_clip=%d"), Projectiles, WithClip);',
    '\t\t\tif (WithClip < 1)',
    '\t\t\t{',
    '\t\t\t\tUE_LOG(LogGB, Error, TEXT("SMOKE pixelvfx fireball FAILED: no projectile in flight carries the baked clip (projectiles=%d)"), Projectiles);',
    '\t\t\t}',
    '\t\t\tShot(TEXT("17_pixelvfx_fireball_flight"));',
    '\t\t}, 0.07f);',
    '\t\tAdd(69.2f + S, TEXT("pixelvfx: screenshot of the Fireball\'s baked explosion"), [](UWorld* World, AGBPlayerCharacter*)',
    '\t\t{',
    '\t\t\tint32 Clips = 0;',
    '\t\t\tfor (TActorIterator<AActor> It(World); It; ++It)',
    '\t\t\t{',
    '\t\t\t\tClips += It->GetClass()->GetName() == TEXT("GBPixelVfxActor") ? 1 : 0;',
    '\t\t\t}',
    '\t\t\tUE_LOG(LogGB, Display, TEXT("SMOKE pixelvfx fireball impact clips=%d"), Clips);',
    '\t\t\tif (Clips < 2)',
    '\t\t\t{',
    '\t\t\t\tUE_LOG(LogGB, Error, TEXT("SMOKE pixelvfx fireball FAILED: %d baked clips in the world (expected 2: the ground fire and the explosion)"), Clips);',
    '\t\t\t}',
    '\t\t\tShot(TEXT("18_pixelvfx_fireball_impact"));',
    '\t\t}, 0.42f);',
    '\t\tAdd(69.3f + S, TEXT("pixelvfx: remove the clips and look ahead again, so the steps after this block are not affected"), [](UWorld* World, AGBPlayerCharacter* Player)',
    '\t\t{',
    '\t\t\tfor (TActorIterator<AActor> It(World); It; ++It)',
    '\t\t\t{',
    '\t\t\t\tif (It->GetClass()->GetName() == TEXT("GBPixelVfxActor"))',
    '\t\t\t\t{',
    '\t\t\t\t\tIt->Destroy();',
    '\t\t\t\t}',
    '\t\t\t}',
    '\t\t\tif (AGBPlayerController* PC = Cast<AGBPlayerController>(Player->GetController()))',
    '\t\t\t{',
    '\t\t\t\tPC->SetControlRotation(FRotator(0.f, PC->GetControlRotation().Yaw, 0.f));',
    '\t\t\t}',
    '\t\t}, 0.55f);',
  ]);
  return rep(s, tail, added, 'shot step tail');
}

const files = [
  ['Glyphbound/Source/Glyphbound/Glyphbound.Build.cs', buildCs],
  ['Glyphbound/Source/Glyphbound/Core/GBDevCommands.cpp', devCommands],
];
const mode = process.argv[2];
for (const [rel, fn] of files) {
  if (mode === 'work') {
    const f = repo + '/' + rel;
    let s = fs.readFileSync(f, 'utf8'); const crlf = s.includes('\r\n'); if (crlf) s = s.split('\r\n').join('\n');
    const out = fn(s);
    fs.writeFileSync(f, crlf ? out.split('\n').join('\r\n') : out);
    console.log('working file patched: ' + rel);
  } else if (mode === 'stage') {
    const head = execFileSync('git', ['-C', repo, 'show', 'HEAD:' + rel], { encoding: 'utf8', maxBuffer: 1 << 26 });
    const crlf = head.includes('\r\n');
    const out = fn(crlf ? head.split('\r\n').join('\n') : head);
    const tmp = process.env.TEMP + '/pvfx_stage_blob.tmp';
    fs.writeFileSync(tmp, crlf ? out.split('\n').join('\r\n') : out);
    const sha = execFileSync('git', ['-C', repo, 'hash-object', '-w', '--path', rel, tmp], { encoding: 'utf8' }).trim();
    execFileSync('git', ['-C', repo, 'update-index', '--cacheinfo', '100644,' + sha + ',' + rel]);
    console.log('staged HEAD + mine: ' + rel + ' (' + sha.slice(0, 8) + ')');
  } else {
    console.log('usage: work | stage'); process.exit(1);
  }
}

