// Fourth pass: in the full run slot 0 no longer holds the Fireball when this block starts (earlier steps change the
// loadout), so the block equips it for the cast and puts the previous spell back when it cleans up.
function devCommandsV4(s) {
  if (s.includes('PixelVfxPreviousSlot0')) return s;
  s = rep(s, L([
    '\t\tAdd(68.72f + S, TEXT("pixelvfx: aim at the floor a few metres ahead"), [](UWorld* World, AGBPlayerCharacter* Player)',
    '\t\t{',
  ]), L([
    '\t\t// Earlier steps change the loadout: the block equips the Fireball in slot 0 and puts the previous spell back at the end.',
    '\t\tstatic FName PixelVfxPreviousSlot0;',
    '\t\tAdd(68.72f + S, TEXT("pixelvfx: aim at the floor a few metres ahead"), [](UWorld* World, AGBPlayerCharacter* Player)',
    '\t\t{',
    '\t\t\tPixelVfxPreviousSlot0 = Player->GetSpellbook()->GetSlotSpell(0);',
    '\t\t\tPlayer->GetSpellbook()->EquipSpell(0, FName(TEXT("Fireball")));',
  ]), 'aim step head');
  s = rep(s, L([
    '\t\t\t\tPC->SetControlRotation(FRotator(0.f, PC->GetControlRotation().Yaw, 0.f));',
    '\t\t\t}',
    '\t\t}, 0.7f);',
  ]), L([
    '\t\t\t\tPC->SetControlRotation(FRotator(0.f, PC->GetControlRotation().Yaw, 0.f));',
    '\t\t\t}',
    '\t\t\tif (!PixelVfxPreviousSlot0.IsNone() && PixelVfxPreviousSlot0 != FName(TEXT("Fireball")))',
    '\t\t\t{',
    '\t\t\t\tPlayer->GetSpellbook()->EquipSpell(0, PixelVfxPreviousSlot0);',
    '\t\t\t}',
    '\t\t}, 0.7f);',
  ]), 'cleanup tail');
  return s;
}

const files = [
  ['Glyphbound/Source/Glyphbound/Glyphbound.Build.cs', buildCs],
  ['Glyphbound/Source/Glyphbound/Core/GBDevCommands.cpp', (s) => devCommandsV4(devCommandsV3(devCommandsV2(devCommands(s))))],
];

